const NEVER_CACHE_PATH_PREFIXES = [
  '/api',
  '/auth',
  '/login',
  '/register',
  '/join',
  '/callback',
  '/rest/v1',
  '/auth/v1',
  '/realtime/v1',
  '/storage/v1',
  '/functions/v1',
]

function isSupabaseHost(hostname) {
  return hostname === 'supabase.co' || hostname.endsWith('.supabase.co')
}

function hasSensitiveHeaders(request) {
  return request.headers.has('authorization') || request.headers.has('apikey')
}

function shouldNeverCache(request, url) {
  if (request.method !== 'GET') return true
  if (url.origin !== self.location.origin) return true
  if (isSupabaseHost(url.hostname) || hasSensitiveHeaders(request)) return true
  if (
    NEVER_CACHE_PATH_PREFIXES.some(
      (prefix) => url.pathname === prefix || url.pathname.startsWith(`${prefix}/`),
    )
  ) {
    return true
  }

  const optimizedSource = url.searchParams.get('url')
  return optimizedSource ? optimizedSource.includes('supabase.co') : false
}

function isCacheableResponse(response) {
  if (!response.ok || response.type !== 'basic') return false
  const cacheControl = response.headers.get('cache-control') ?? ''
  return !/(?:no-store|private)/i.test(cacheControl)
}

function isDocumentRequest(request) {
  const accept = request.headers.get('accept') ?? ''
  return (
    request.mode === 'navigate' ||
    request.destination === 'document' ||
    accept.includes('text/html')
  )
}

function isNextDataRequest(request, url) {
  const accept = request.headers.get('accept') ?? ''
  return (
    url.searchParams.has('_rsc') ||
    request.headers.get('rsc') === '1' ||
    accept.includes('text/x-component')
  )
}

function isStaticRequest(request, url) {
  if (url.pathname.startsWith('/_next/static/')) return true
  if (url.pathname.startsWith('/_next/image')) return true
  if (/^\/(?:images|audio|icons|fonts)\//.test(url.pathname)) return true
  return ['audio', 'font', 'image', 'script', 'style', 'video'].includes(request.destination)
}

async function trimCache(cache, maxEntries) {
  const keys = await cache.keys()
  const overflow = keys.length - maxEntries
  if (overflow > 0) {
    await Promise.all(keys.slice(0, overflow).map((key) => cache.delete(key)))
  }
}

async function fetchWithTimeout(request, timeoutMs = 8000) {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), timeoutMs)
  try {
    return await fetch(request, { signal: controller.signal })
  } finally {
    clearTimeout(timeout)
  }
}

async function fetchAndCacheAsset(urlOrRequest) {
  const request =
    typeof urlOrRequest === 'string'
      ? new Request(urlOrRequest, {
          cache: 'reload',
          credentials: 'same-origin',
        })
      : urlOrRequest
  const url = new URL(request.url)
  if (shouldNeverCache(request, url)) return null

  const response = await fetchWithTimeout(request)
  if (!isCacheableResponse(response)) return response

  const cache = await caches.open(STATIC_CACHE)
  await cache.put(request, response.clone())
  await trimCache(cache, MAX_STATIC_ENTRIES)
  return response
}

function discoverStaticAssets(html) {
  const decoded = html.replaceAll('&amp;', '&').replaceAll('\\u0026', '&')
  const matches =
    decoded.match(
      /\/(?:_next\/(?:static\/|image\?)|images\/|audio\/|icons\/|fonts\/)[^"'<>\s,)]+/g,
    ) ?? []

  return [...new Set(matches.map((asset) => asset.replace(/\\+$/, '')))].filter((asset) => {
    try {
      const url = new URL(asset, self.location.origin)
      if (url.pathname.startsWith('/_next/static/') && !/\.(?:css|js|woff2?)$/.test(url.pathname)) {
        return false
      }
      const request = new Request(url)
      return !shouldNeverCache(request, url)
    } catch {
      return false
    }
  })
}

async function precacheCoreRoute(pathname) {
  const request = new Request(pathname, {
    cache: 'reload',
    credentials: 'same-origin',
  })
  const response = await fetchWithTimeout(request)
  if (!isCacheableResponse(response)) return []

  const finalUrl = new URL(response.url)
  if (finalUrl.origin !== self.location.origin || finalUrl.pathname !== pathname) return []

  const shell = await caches.open(SHELL_CACHE)
  await shell.put(pathname, response.clone())

  const contentType = response.headers.get('content-type') ?? ''
  if (!contentType.includes('text/html')) return []
  return discoverStaticAssets(await response.text())
}

async function inBatches(items, batchSize, worker) {
  for (let index = 0; index < items.length; index += batchSize) {
    const batch = items.slice(index, index + batchSize)
    await Promise.allSettled(batch.map(worker))
  }
}

async function precacheCore() {
  const discoveredAssets = new Set(CORE_ASSETS)

  await inBatches(CORE_ROUTES, 4, async (route) => {
    const assets = await precacheCoreRoute(route)
    assets.forEach((asset) => discoveredAssets.add(asset))
  })

  await inBatches([...discoveredAssets], 8, fetchAndCacheAsset)
}

async function cacheFirstStatic(request) {
  const cache = await caches.open(STATIC_CACHE)
  const cached = await cache.match(request)
  if (cached) return cached

  const response = await fetch(request)
  if (isCacheableResponse(response)) {
    await cache.put(request, response.clone())
    await trimCache(cache, MAX_STATIC_ENTRIES)
  }
  return response
}

async function networkFirstPage(request, url) {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), 4000)

  try {
    const response = await fetch(request, { signal: controller.signal })
    if (CORE_ROUTE_PATHS.has(url.pathname) && isCacheableResponse(response)) {
      const shell = await caches.open(SHELL_CACHE)
      await shell.put(url.pathname, response.clone())
    }
    return response
  } catch {
    const shell = await caches.open(SHELL_CACHE)
    const cached = await shell.match(url.pathname)
    if (cached) return cached

    return new Response('אין חיבור לרשת והעמוד הזה עדיין לא נשמר במכשיר.', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    })
  } finally {
    clearTimeout(timeout)
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil(precacheCore().finally(() => self.skipWaiting()))
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) =>
        Promise.all(
          names
            .filter((name) => name.startsWith(CACHE_PREFIX) && !CURRENT_CACHES.has(name))
            .map((name) => caches.delete(name)),
        ),
      )
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const { request } = event
  const url = new URL(request.url)

  if (shouldNeverCache(request, url)) return
  if (isNextDataRequest(request, url)) return

  if (isDocumentRequest(request)) {
    event.respondWith(networkFirstPage(request, url))
    return
  }

  if (isStaticRequest(request, url)) {
    event.respondWith(cacheFirstStatic(request))
  }
})
